                                    });
                                }
                            }
                            Err(e) => {
                                warn!("[{section}].config_roots glob error: {e}");
                            }
                        }
                    }
                }
                Err(e) => {
                    warn!("[{section}].config_roots invalid glob pattern '{pattern}': {e}");
