/// settings-excluded managers are hard errors.
pub(crate) fn packages_from_requests(
    by_mgr: IndexMap<String, Vec<PackageRequest>>,
) -> eyre::Result<Vec<ManagerPackages>> {
    resolve_managers(by_mgr, IndexMap::new(), true)
}

pub(crate) fn attach_brew_tap_urls(
    config: &Config,
    by_mgr: &mut IndexMap<String, Vec<PackageRequest>>,
) {
    let brew_taps = brew_taps_from_config(config);
    for mgr in ["brew", "brew-cask"] {
        if let Some(requests) = by_mgr.get_mut(mgr) {
            for request in requests {
                request.tap_url =
                    brew_tap_name(&request.name).and_then(|tap| brew_taps.get(tap).cloned());
            }
        }
    }
}

/// Aggregate `[bootstrap.packages]` across all loaded config files.
///
/// Keys union global -> local; a more local config overrides the declaration
/// of a key the global config declared. Malformed keys and unknown managers
/// warn (forward compatibility) and are skipped. The
/// `system_packages.managers` setting restricts which managers are used at
/// all.
pub(crate) fn packages_from_config(config: &Config) -> Vec<ManagerPackages> {
    let brew_taps = brew_taps_from_config(config);
    packages_from_config_files_with_brew_taps(&config.config_files, &brew_taps, true)
}

/// Merge raw `[bootstrap.packages]` declarations inherited by `target` without
/// applying host filters. Configs more local than the target are excluded.
#[cfg(unix)]
pub(crate) fn package_configs_for_target(
    config: &Config,
    target: &Path,
) -> IndexMap<String, PackageTomlConfig> {
    package_configs_from_config_files_for_target(&config.config_files, target)
}

/// Package requests for declared package plugins that are not installed yet.
///
/// During a bootstrap dry run, plugin installation is intentionally not
/// persisted, but the later package phase still needs to show the packages
/// that the newly declared plugins would manage.
pub(crate) fn pending_plugin_packages_from_config(
    config: &Config,
) -> IndexMap<String, Vec<PackageRequest>> {
    pending_plugin_packages_from_config_including_disabled(config)
        .into_iter()
        .filter(|(name, _)| package_manager_is_enabled(name))
        .collect()
}

/// All package requests for declared, not-yet-installed package plugins,
/// including managers excluded by `system_packages.managers`. Resource plans
/// use this broader view so excluded declarations remain visible as unknown.
pub(crate) fn pending_plugin_packages_from_config_including_disabled(
    config: &Config,
) -> IndexMap<String, Vec<PackageRequest>> {
    let declared = plugins_from_config(config);
    let brew_taps = brew_taps_from_config(config);
    let installed = packages::all_managers()
        .into_iter()
        .map(|manager| manager.name().to_string())
        .collect::<std::collections::HashSet<_>>();
    package_requests_from_config_files(&config.config_files, &brew_taps, true)
        .0
        .into_iter()
        .filter(|(name, _)| declared.contains_key(name) && !installed.contains(name))
        .collect()
}

pub(crate) fn package_manager_is_enabled(name: &str) -> bool {
    crate::config::Settings::get()
        .system_packages
        .managers
        .as_ref()
        .is_none_or(|names| names.iter().any(|enabled| enabled == name))
}

/// Aggregate `[bootstrap.packages]` from the current merged config plus every
/// tracked config file, mirroring the way `mise prune` protects tool versions
/// still referenced by other projects.
#[cfg(unix)]
pub(crate) async fn packages_from_config_and_tracked_config_files(
    config: &Arc<Config>,
) -> Result<Vec<ManagerPackages>> {
    let tracked_config_files = config.get_tracked_config_files().await?;
    packages_from_config_files_and_tracked_config_files(&config.config_files, &tracked_config_files)
}

/// Return requests for one manager from the current config and every trusted,
/// loadable tracked config. This does not resolve unrelated managers, which
/// keeps plugin pruning portable when shared configs contain host-specific
/// package managers.
pub(crate) async fn package_requests_for_manager_from_config_and_tracked_config_files(
    config: &Arc<Config>,
    manager: &str,
) -> Result<Vec<PackageRequest>> {
    let tracked = config.get_tracked_config_files().await?;
    let mut requests =
        package_requests_from_config_files(&config.config_files, &IndexMap::new(), false)
            .0
            .shift_remove(manager)
            .unwrap_or_default();
    for request in package_requests_from_config_files(&tracked, &IndexMap::new(), false)
        .0
        .shift_remove(manager)
        .unwrap_or_default()
    {
        if !requests
            .iter()
            .any(|existing| existing.name == request.name && existing.version == request.version)
        {
            requests.push(request);
        }
    }
    Ok(requests)
}

#[cfg(unix)]
fn packages_from_config_files_and_tracked_config_files(
    current_config_files: &ConfigMap,
    tracked_config_files: &ConfigMap,
) -> Result<Vec<ManagerPackages>> {
    let mut by_mgr: IndexMap<String, Vec<PackageRequest>> = IndexMap::new();
    let mut manager_options = IndexMap::new();
    let current_brew_taps = brew_taps_from_config_files(current_config_files);
    merge_manager_packages(
        &mut by_mgr,
        &mut manager_options,
        packages_from_config_files_with_brew_taps(current_config_files, &current_brew_taps, false),
    );

    let mut tracked_brew_taps = current_brew_taps;
    for (tap, url) in brew_taps_from_config_files(tracked_config_files) {
        tracked_brew_taps.insert(tap, url);
    }
    merge_manager_packages(
        &mut by_mgr,
        &mut manager_options,
        packages_from_config_files_with_brew_taps(tracked_config_files, &tracked_brew_taps, false),
    );

    resolve_managers(by_mgr, manager_options, false)
}

#[cfg(unix)]
fn merge_manager_packages(
    by_mgr: &mut IndexMap<String, Vec<PackageRequest>>,
    manager_options: &mut IndexMap<String, ManagerPackageOptions>,
    manager_packages: Vec<ManagerPackages>,
) {
    for mp in manager_packages {
        let manager_name = mp.manager.name().to_string();
        let requests = by_mgr.entry(manager_name.clone()).or_default();
        for request in mp.requests {
            let adopt = mp.options.brew_cask_adopt(&request.name);
            match requests.iter_mut().find(|existing| {
                existing.name == request.name && existing.version == request.version
            }) {
                Some(existing) if existing.tap_url.is_none() => {
                    existing.tap_url = request.tap_url;
                }
                Some(_) => {}
                None => {
                    if adopt {
                        let options =
                            manager_options
                                .entry(manager_name.clone())
                                .or_insert_with(|| ManagerPackageOptions::BrewCask {
                                    adopt: BTreeSet::new(),
                                });
                        if let ManagerPackageOptions::BrewCask { adopt } = options {
                            adopt.insert(request.name.clone());
                        }
                    }
                    requests.push(request);
                }
            }
        }
    }
}

/// Aggregate `[bootstrap.packages]` across a specific set of config files.
pub(crate) fn packages_from_config_files(config_files: &ConfigMap) -> Vec<ManagerPackages> {
