/// Aggregate `[bootstrap.packages]` from the current merged config plus every
/// tracked config file, mirroring the way `mise prune` protects tool versions
/// still referenced by other projects.
#[cfg(unix)]
pub(crate) async fn packages_from_config_and_tracked_config_files(
    config: &Arc<Config>,
) -> Result<Vec<ManagerPackages>> {
    let tracked_config_files = config.get_tracked_config_files().await?;
    packages_from_config_files_and_tracked_config_files(&config.config_files, &tracked_config_files)
}

/// Return requests for one manager from the current config and every trusted,
/// loadable tracked config. This does not resolve unrelated managers, which
/// keeps plugin pruning portable when shared configs contain host-specific
/// package managers.
pub(crate) async fn package_requests_for_manager_from_config_and_tracked_config_files(
    config: &Arc<Config>,
    manager: &str,
) -> Result<Vec<PackageRequest>> {
    let tracked = config.get_tracked_config_files().await?;
    let mut requests =
        package_requests_from_config_files(&config.config_files, &IndexMap::new(), false)
            .0
            .shift_remove(manager)
            .unwrap_or_default();
    for request in package_requests_from_config_files(&tracked, &IndexMap::new(), false)
        .0
        .shift_remove(manager)
        .unwrap_or_default()
    {
        if !requests
            .iter()
            .any(|existing| existing.name == request.name && existing.version == request.version)
        {
            requests.push(request);
        }
    }
    Ok(requests)
}

#[cfg(unix)]
fn packages_from_config_files_and_tracked_config_files(
    current_config_files: &ConfigMap,
    tracked_config_files: &ConfigMap,
) -> Result<Vec<ManagerPackages>> {
    let mut by_mgr: IndexMap<String, Vec<PackageRequest>> = IndexMap::new();
    let mut manager_options = IndexMap::new();
    let current_brew_taps = brew_taps_from_config_files(current_config_files);
    merge_manager_packages(
        &mut by_mgr,
        &mut manager_options,
        packages_from_config_files_with_brew_taps(current_config_files, &current_brew_taps, false),
    );

    let mut tracked_brew_taps = current_brew_taps;
    for (tap, url) in brew_taps_from_config_files(tracked_config_files) {
        tracked_brew_taps.insert(tap, url);
    }
    merge_manager_packages(
        &mut by_mgr,
        &mut manager_options,
        packages_from_config_files_with_brew_taps(tracked_config_files, &tracked_brew_taps, false),
    );

    resolve_managers(by_mgr, manager_options, false)
}

#[cfg(unix)]
fn merge_manager_packages(
    by_mgr: &mut IndexMap<String, Vec<PackageRequest>>,
    manager_options: &mut IndexMap<String, ManagerPackageOptions>,
    manager_packages: Vec<ManagerPackages>,
) {
    for mp in manager_packages {
        let manager_name = mp.manager.name().to_string();
        let requests = by_mgr.entry(manager_name.clone()).or_default();
        for request in mp.requests {
            let adopt = mp.options.brew_cask_adopt(&request.name);
            match requests.iter_mut().find(|existing| {
                existing.name == request.name && existing.version == request.version
            }) {
                Some(existing) if existing.tap_url.is_none() => {
                    existing.tap_url = request.tap_url;
                }
                Some(_) => {}
                None => {
                    if adopt {
                        let options =
                            manager_options
                                .entry(manager_name.clone())
                                .or_insert_with(|| ManagerPackageOptions::BrewCask {
                                    adopt: BTreeSet::new(),
                                });
                        if let ManagerPackageOptions::BrewCask { adopt } = options {
                            adopt.insert(request.name.clone());
                        }
                    }
                    requests.push(request);
                }
            }
        }
    }
}

/// Aggregate `[bootstrap.packages]` across a specific set of config files.
pub(crate) fn packages_from_config_files(config_files: &ConfigMap) -> Vec<ManagerPackages> {
    packages_from_config_files_with_brew_taps(config_files, &IndexMap::new(), true)
}

fn packages_from_config_files_with_brew_taps(
    config_files: &ConfigMap,
    brew_taps: &IndexMap<String, String>,
    filter_env: bool,
) -> Vec<ManagerPackages> {
    let (requests, options) =
        package_requests_from_config_files(config_files, brew_taps, filter_env);
    resolve_managers(requests, options, false).expect("non-strict resolve is infallible")
}

fn package_requests_from_config_files(
    config_files: &ConfigMap,
    brew_taps: &IndexMap<String, String>,
    filter_env: bool,
) -> (
    IndexMap<String, Vec<PackageRequest>>,
    IndexMap<String, ManagerPackageOptions>,
) {
    let merged = package_configs_from_config_files(config_files);
    let mut by_mgr: IndexMap<String, Vec<PackageRequest>> = IndexMap::new();
    #[cfg(unix)]
    let brew_adopt = brew_adopt_from_config_files(config_files);
    #[cfg(unix)]
    let mut cask_adopt = BTreeSet::new();
    for (spec, package) in merged {
        if !package.is_os_supported() {
            debug!("[bootstrap.packages]: skipping '{spec}', not enabled for this platform");
            continue;
        }
        if filter_env && !package.is_env_supported(&crate::env::MISE_ENV_WITH_AUTO) {
            debug!("[bootstrap.packages]: skipping '{spec}', not enabled for this environment");
            continue;
        }
        match parse_spec(&spec) {
            Ok((mgr, name)) => {
                let version = package.version();
                let version = (version != "latest").then(|| version.to_string());
                if let Err(err) = validate_package_name(&mgr, &name) {
                    warn!("[bootstrap.packages]: {err}");
                    continue;
                }
                let tap_url = if is_brew_manager(&mgr) {
                    brew_tap_name(&name).and_then(|tap| brew_taps.get(tap).cloned())
                } else {
                    None
                };
                let adopt_requested = package.adopt();
                if adopt_requested.is_some() && mgr != "brew-cask" {
                    warn!(
                        "[bootstrap.packages]: adopt is only supported for brew-cask entries; ignoring it for '{spec}'"
                    );
                }
                #[cfg(unix)]
                if mgr == "brew-cask" && adopt_requested.unwrap_or(brew_adopt) {
                    cask_adopt.insert(name.clone());
                }
                by_mgr.entry(mgr).or_default().push(PackageRequest {
                    name,
                    version,
                    tap_url,
                    desired: package.desired(),
                });
            }
            Err(err) => warn!("[bootstrap.packages]: {err}"),
        }
    }
    #[cfg(unix)]
    let options = if cask_adopt.is_empty() {
        IndexMap::new()
    } else {
        IndexMap::from([(
            "brew-cask".to_string(),
            ManagerPackageOptions::BrewCask { adopt: cask_adopt },
        )])
    };
    #[cfg(not(unix))]
    let options = IndexMap::new();
    (by_mgr, options)
}

